/**
 * 섹션 1 · 유닛 1 — 안녕하세요?
 * 출처: 서울대 한국어 1A 1과
 *
 * 배우는 것
 *   인사말        안녕하세요? / 만나서 반가워요 / 안녕히 가세요·계세요
 *   국적          한국·미국·중국·일본·영국·프랑스·독일·호주 + N 사람
 *   직업          선생님·학생·의사·회사원·요리사·기자·가수·군인
 *   문법          N은/는 N이에요/예요   ·   N입니까?/N입니다   ·   N이/가 아닙니다
 *
 * 유닛 1 규칙
 *   - 타이핑 계열(type_answer / translate_type / listen_type / listen_fill)은 넣지 않는다.
 *     처음 배우는 사람이 한글 자판을 못 친다. 섹션 중반부터 들어간다.
 *   - 빈칸은 전부 단일 빈칸(sentencePrefix + sentenceSuffix). 다중 빈칸은 섹션 2부터.
 *   - word_matching / audio_match 의 korean 은 짧은 단어만. 문장을 넣으면 버튼이 깨진다.
 *   - speaking 은 한 사람이 말하는 단어·짧은 문장만. 두 사람 대화 금지.
 *   - 같은 타입을 연달아 배치하지 않는다.
 *   - options 는 정답 개수보다 오답을 2~3개 더 넣고, 순서를 섞어서 적는다.
 *   - translate_builder 의 instruction 은 공용 문구가 아니라 "옮겨야 할 문장"이다.
 *     화면이 제목에 고정 문구를 쓰고 말풍선에 instruction 을 띄우기 때문에,
 *     여기에 학습자 언어로 뜻을 적어야 무엇을 만들지 알 수 있다.
 *     ko 에는 정답을 그대로 적지 않는다 (적으면 답을 베끼게 된다).
 */

